import type {
  ChangeRequest,
  CommentChangeItem,
  StaticPreviewChangeTarget,
  VariantDirectionBrief,
} from '../types/change-request-types';
import type { WorkerFidelity } from '../agent-variants/contracts';

export function isSingleVariantRequestBatch(intent: ChangeRequest): boolean {
  if (intent.changes.length !== 1) return false;
  const item = intent.changes[0];
  return item.kind === 'comment' && Boolean(item.variantRequest);
}

export function isMixedVariantBatch(intent: ChangeRequest): boolean {
  if (intent.changes.length <= 1) return false;
  return intent.changes.some(
    (c) => c.kind === 'comment' && Boolean(c.variantRequest),
  );
}

export type StaticPreviewRefineTargetInstruction = {
  target: StaticPreviewChangeTarget;
  instruction: string;
  count?: number;
  briefs?: VariantDirectionBrief[];
  runLabel?: string;
  fidelity?: WorkerFidelity;
  element?: CommentChangeItem['element'];
  requestId?: string;
};

const staticPreviewInstructionTargetKey = (
  target: StaticPreviewChangeTarget,
): string => `${target.sessionId}:${target.variantId}`;

const getCommentStaticPreviewTarget = (
  comment: CommentChangeItem,
  fallbackTarget?: StaticPreviewChangeTarget,
): StaticPreviewChangeTarget | undefined =>
  comment.staticPreviewTarget ?? fallbackTarget;

export const collectStaticPreviewRefineTargetInstructions = (
  request: ChangeRequest,
): StaticPreviewRefineTargetInstruction[] => {
  const groups = new Map<string, StaticPreviewRefineTargetInstruction>();
  const requestId = request.agentRunId ?? request.traceId;
  for (const change of request.changes) {
    if (change.kind !== 'comment') continue;
    const target = getCommentStaticPreviewTarget(
      change,
      request.staticPreviewTarget,
    );
    if (!target) continue;
    const key = staticPreviewInstructionTargetKey(target);
    const count = change.variantRequest?.count;
    const briefs = change.variantRequest?.briefs;
    const runLabel = change.variantRequest?.runLabel;
    const fidelity = change.variantRequest?.fidelity;
    const existing = groups.get(key);
    if (existing) {
      existing.instruction = `${existing.instruction}\n\n${change.instruction}`;
      if (count != null) {
        existing.count = Math.max(existing.count ?? 0, count);
      }
      if (briefs) {
        existing.briefs = briefs;
      }
      if (runLabel) {
        existing.runLabel = runLabel;
      }
      if (fidelity) {
        existing.fidelity = fidelity;
      }
      existing.element = existing.element ?? change.element;
    } else {
      groups.set(key, {
        target,
        instruction: change.instruction,
        ...(count != null ? { count } : {}),
        ...(briefs ? { briefs } : {}),
        ...(runLabel ? { runLabel } : {}),
        ...(fidelity ? { fidelity } : {}),
        element: change.element,
        ...(requestId ? { requestId } : {}),
      });
    }
  }
  return [...groups.values()];
};

export function withDerivedStaticPreviewTargets(
  request: ChangeRequest,
): ChangeRequest {
  const deriveFromTarget = (
    target: ChangeRequest['target'],
  ): ChangeRequest['staticPreviewTarget'] =>
    target?.kind === 'variant'
      ? {
          kind: 'static_preview',
          sessionId: target.sessionId,
          variantId: target.variantId,
        }
      : undefined;

  return {
    ...request,
    staticPreviewTarget:
      request.staticPreviewTarget ?? deriveFromTarget(request.target),
    changes: request.changes.map((change) => {
      if (change.kind !== 'comment' || change.staticPreviewTarget)
        return change;
      const derived =
        deriveFromTarget(change.target) ?? deriveFromTarget(request.target);
      return derived ? { ...change, staticPreviewTarget: derived } : change;
    }),
  };
}
